function productImage(value){return /^https:\/\//.test(value||'')||value?.startsWith('/api/images/')||value?.startsWith('/assets/')?esc(value):'/assets/'+esc(value);}
function photoEditor(p){return `<fieldset class="photo-editor"><legend>Fotos</legend><p class="muted">Até 8 fotos (JPG, PNG ou WebP · máx. 8 MB)</p><div class="photo-list">${(p.photos||[]).map(photo=>`<article><img src="${esc(photo.url)}" alt="Foto de ${esc(p.name)}"><span>${p.image===photo.url?'Capa':''}</span><button type="button" data-photo-cover="${photo.id}" ${p.image===photo.url?'disabled':''}>Usar como capa</button><button type="button" data-photo-delete="${photo.id}">Remover</button></article>`).join('')}</div><label class="photo-upload">Adicionar fotos<input type="file" data-photo-upload accept="image/jpeg,image/png,image/webp" multiple ${(p.photos||[]).length>=8?'disabled':''}></label><p class="photo-message" role="status" aria-live="polite"></p></fieldset>`;}
function productGallery(p){const photos=p.photos?.length?p.photos:[];return `<img class="gallery-main" src="${productImage(p.image)}" alt="${esc(p.name)}">${photos.length>1?`<div class="gallery-thumbs">${photos.map(photo=>`<button type="button" data-gallery="${esc(photo.url)}" aria-label="Ver foto de ${esc(p.name)}" aria-pressed="${p.image===photo.url}"><img src="${esc(photo.url)}" alt=""></button>`).join('')}</div>`:''}`;}
function refreshPhotos(form,p){const current=products.find(x=>x.id===p.id);if(current)Object.assign(current,p);form.querySelector('.photo-editor').outerHTML=photoEditor(p);form.querySelector(':scope > img').src=p.image.startsWith('/api/')?p.image:'/assets/'+p.image;}
document.addEventListener('change',async e=>{const input=e.target;if(!input.matches('[data-photo-upload]'))return;const form=input.closest('[data-product]'),fieldset=input.closest('fieldset'),message=fieldset.querySelector('.photo-message'),files=[...input.files];if(!files.length)return;const count=products.find(p=>p.id===form.dataset.product).photos?.length||0;if(count+files.length>8){message.textContent='Escolha no máximo '+(8-count)+' fotos.';input.value='';return;}if(files.some(f=>f.size>8*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){message.textContent='Use JPG, PNG ou WebP de até 8 MB por foto.';input.value='';return;}fieldset.disabled=true;let saved=0,latest;try{for(const file of files){message.textContent=`Enviando foto ${saved+1} de ${files.length}…`;const base64=await prepareUpload(file);latest=await api('admin/products/'+form.dataset.product+'/photos','POST',{base64});saved++;}refreshPhotos(form,latest);form.querySelector('.photo-message').textContent=`${saved} foto(s) salva(s).`;}
catch(err){if(latest)refreshPhotos(form,latest);form.querySelector('.photo-message').textContent=`${saved? saved+' foto(s) salva(s). ':''}${err.message||'Falha ao enviar. Tente novamente.'}`;}finally{const el=form.querySelector('.photo-editor');el.disabled=false;el.querySelector('input').value='';}});
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.gallery){const box=button.closest('.detail-photo');box.querySelector('.gallery-main').src=button.dataset.gallery;box.querySelectorAll('[data-gallery]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));return;}const id=button.dataset.photoCover||button.dataset.photoDelete;if(!id)return;const form=button.closest('[data-product]'),fieldset=button.closest('fieldset');fieldset.disabled=true;try{const p=await api('admin/products/'+form.dataset.product+'/photos',button.dataset.photoCover?'PATCH':'DELETE',{id});refreshPhotos(form,p);}catch(err){fieldset.querySelector('.photo-message').textContent=err.message;}finally{form.querySelector('.photo-editor').disabled=false;}});

async function prepareUpload(file){const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL('image/webp',0.86).split(',')[1];if(encoded.length>3900000)throw new Error('Esta foto ainda é muito grande. Escolha uma versão menor.');return encoded;}finally{bitmap.close();}}
